select throws_ok($$select * from public.provision_internal_admin_restaurant_training_program('4d100000-0000-4000-8000-000000000099','4d200000-0000-4000-8000-000000000001','{"en":"Restaurant Training","ar":"تدريب المطعم","id":"Pelatihan Restoran","hi":"रेस्तरां प्रशिक्षण","fil":"Pagsasanay sa Restaurant"}','{"en":"Required learning","ar":"التعلم المطلوب","id":"Pembelajaran wajib","hi":"आवश्यक प्रशिक्षण","fil":"Kinakailangang pagsasanay"}','{"en":"Baladiyah","ar":"البلدية","id":"Baladiyah","hi":"बलदिया","fil":"Baladiyah"}','{"en":"Restaurant SOP","ar":"إجراءات تشغيل المطعم","id":"SOP Restoran","hi":"रेस्तरां एसओपी","fil":"SOP ng Restaurant"}')$$,'42501','Training program access denied','non-admin provisioning is denied');
select lives_ok($$select * from public.provision_internal_admin_restaurant_training_program('4d100000-0000-4000-8000-000000000001','4d200000-0000-4000-8000-000000000001','{"en":"Restaurant Training","ar":"تدريب المطعم","id":"Pelatihan Restoran","hi":"रेस्तरां प्रशिक्षण","fil":"Pagsasanay sa Restaurant"}','{"en":"Required learning","ar":"التعلم المطلوب","id":"Pembelajaran wajib","hi":"आवश्यक प्रशिक्षण","fil":"Kinakailangang pagsasanay"}','{"en":"Baladiyah","ar":"البلدية","id":"Baladiyah","hi":"बलदिया","fil":"Baladiyah"}','{"en":"Restaurant SOP","ar":"إجراءات تشغيل المطعم","id":"SOP Restoran","hi":"रेस्तरां एसओपी","fil":"SOP ng Restaurant"}')$$,'authorized organization provisioning succeeds');
