select throws_ok($$select * from public.provision_internal_admin_restaurant_training_program('4d100000-0000-4000-8000-000000000001','4d200000-0000-4000-8000-000000000001','{"en":"Changed","ar":"تغيير","id":"Berubah","hi":"बदला","fil":"Binago"}','{"en":"Required learning","ar":"التعلم المطلوب","id":"Pembelajaran wajib","hi":"आवश्यक प्रशिक्षण","fil":"Kinakailangang pagsasanay"}','{"en":"Baladiyah","ar":"البلدية","id":"Baladiyah","hi":"बलदिया","fil":"Baladiyah"}','{"en":"Restaurant SOP","ar":"إجراءات تشغيل المطعم","id":"SOP Restoran","hi":"रेस्तरां एसओपी","fil":"SOP ng Restaurant"}')$$,'55000','Restaurant Training program conflicts with existing content','conflicting provisioning fails closed');

